export const ASN1_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/asn1-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getAsn1StdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(ASN1_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
